CREATE SCHEMA IF NOT EXISTS truss; COMMENT ON SCHEMA truss IS 'truss-layout qualified-property-0.15 REVIEW ONLY - unqualified'; CREATE TABLE truss.setting (key text PRIMARY KEY, value jsonb NOT NULL); INSERT INTO truss.setting VALUES ('journal_mode', '"engine"'); INSERT INTO truss.setting VALUES ('key_reuse', '"forbid"'); CREATE TABLE truss.module_access (document_id text NOT NULL COLLATE pg_catalog."C", module text NOT NULL COLLATE pg_catalog."C", reader_role text NOT NULL COLLATE pg_catalog."C", writer_role text NOT NULL COLLATE pg_catalog."C", CONSTRAINT module_access_qualified_pk PRIMARY KEY (document_id, module), CONSTRAINT module_access_roles_differ CHECK (reader_role <> writer_role)); CREATE TABLE truss.schema_rev (rev int PRIMARY KEY, accepted_at timestamptz NOT NULL DEFAULT now(), origin jsonb NOT NULL DEFAULT ('{}'::jsonb), CONSTRAINT schema_rev_origin_is_object CHECK (jsonb_typeof(origin) = 'object')); INSERT INTO truss.schema_rev VALUES (0, now(), '{}'); CREATE TABLE truss.schema_head (id int PRIMARY KEY CHECK (id = 1), rev int NOT NULL REFERENCES truss.schema_rev (rev)); INSERT INTO truss.schema_head VALUES (1, 0); CREATE TABLE truss.schema_doc (rev int NOT NULL REFERENCES truss.schema_rev (rev), ord int NOT NULL, doc_id text NOT NULL, doc_revision text NOT NULL, umf_version text NOT NULL, content_sha256 text NOT NULL, document text NOT NULL, validation jsonb NOT NULL, PRIMARY KEY (rev, ord), UNIQUE (rev, doc_id)); CREATE TABLE truss.schema_change (rev int NOT NULL REFERENCES truss.schema_rev (rev), seq int NOT NULL, kind text NOT NULL CHECK (kind IN ('type', 'prop', 'rel')), def_id int NOT NULL, before jsonb NOT NULL, after jsonb NOT NULL, PRIMARY KEY (rev, seq)); CREATE TABLE truss.type_def (document_id text NOT NULL COLLATE pg_catalog."C", type_id int PRIMARY KEY, module text NOT NULL COLLATE pg_catalog."C", element text NOT NULL COLLATE pg_catalog."C", kind text NOT NULL, provisional boolean NOT NULL DEFAULT false, since_rev int NOT NULL REFERENCES truss.schema_rev (rev), doc_ord int, retired_rev int REFERENCES truss.schema_rev (rev), lineage_profile text NOT NULL COLLATE pg_catalog."C", lineage_bytes bytea NOT NULL, lineage_sha256 bytea GENERATED ALWAYS AS (pg_catalog.sha256(lineage_bytes)) STORED, CONSTRAINT type_def_lineage_profile_nonempty CHECK (octet_length(lineage_profile) > 0), CONSTRAINT type_def_lineage_bytes_nonempty CHECK (octet_length(lineage_bytes) > 0), FOREIGN KEY (since_rev, doc_ord) REFERENCES truss.schema_doc (rev, ord)); CREATE TABLE truss.prop_def (prop_id int PRIMARY KEY, type_id int NOT NULL REFERENCES truss.type_def (type_id), element text NOT NULL, name text NOT NULL, scalar_type text, nullability text NOT NULL, cardinality text NOT NULL, facets jsonb, item jsonb, home text NOT NULL DEFAULT 'json' CHECK (home IN ('json', 'row')), since_rev int NOT NULL REFERENCES truss.schema_rev (rev), doc_ord int NOT NULL, retired_rev int REFERENCES truss.schema_rev (rev), UNIQUE (type_id, name), UNIQUE (type_id, element), FOREIGN KEY (since_rev, doc_ord) REFERENCES truss.schema_doc (rev, ord)); CREATE TABLE truss.key_def (type_id int NOT NULL REFERENCES truss.type_def (type_id), key_id text NOT NULL, key_num smallint NOT NULL, prop_ids int[] NOT NULL, is_primary boolean NOT NULL, since_rev int NOT NULL REFERENCES truss.schema_rev (rev), retired_rev int REFERENCES truss.schema_rev (rev), PRIMARY KEY (type_id, key_id), UNIQUE (type_id, key_num)); CREATE TABLE truss.rel_def (document_id text NOT NULL COLLATE pg_catalog."C", rel_type_id int PRIMARY KEY, module text NOT NULL COLLATE pg_catalog."C", rel_id text NOT NULL COLLATE pg_catalog."C", name text NOT NULL, source_min int NOT NULL, source_max int, target_min int NOT NULL, target_max int, lifecycle text NOT NULL, directed boolean NOT NULL, target_key text, composition boolean NOT NULL DEFAULT false, assoc_type_id int REFERENCES truss.type_def (type_id), inverse text, since_rev int NOT NULL REFERENCES truss.schema_rev (rev), doc_ord int NOT NULL, retired_rev int REFERENCES truss.schema_rev (rev), FOREIGN KEY (since_rev, doc_ord) REFERENCES truss.schema_doc (rev, ord)); CREATE TABLE truss.rel_endpoint (rel_type_id int NOT NULL REFERENCES truss.rel_def (rel_type_id), source_type int NOT NULL REFERENCES truss.type_def (type_id), target_type int NOT NULL REFERENCES truss.type_def (type_id), PRIMARY KEY (rel_type_id, source_type, target_type)); CREATE SEQUENCE truss.id_seq; CREATE TABLE truss.object (id bigint NOT NULL DEFAULT nextval('truss.id_seq'), type_id int NOT NULL REFERENCES truss.type_def (type_id), props jsonb NOT NULL DEFAULT ('{}'::jsonb), retained jsonb, root_id bigint, root_type int, rev int NOT NULL REFERENCES truss.schema_rev (rev), ver bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), updated_at timestamptz NOT NULL DEFAULT clock_timestamp(), CONSTRAINT object_pkey PRIMARY KEY (id, type_id), CONSTRAINT object_props_is_object CHECK (jsonb_typeof(props) = 'object'), CONSTRAINT object_retained_is_object CHECK (retained IS NULL OR jsonb_typeof(retained) = 'object'), CONSTRAINT object_root_both_or_neither CHECK ((root_id IS NULL) = (root_type IS NULL)), CONSTRAINT object_root_fk FOREIGN KEY (root_id, root_type) REFERENCES truss.object (id, type_id) ON DELETE RESTRICT); CREATE INDEX object_type_id ON truss.object USING btree (type_id, id); CREATE TABLE truss.edge (id bigint PRIMARY KEY DEFAULT nextval('truss.id_seq'), rel_type_id int NOT NULL, source_id bigint NOT NULL, source_type int NOT NULL, target_id bigint NOT NULL, target_type int NOT NULL, props jsonb NOT NULL DEFAULT ('{}'::jsonb), order_key text COLLATE "C", rev int NOT NULL REFERENCES truss.schema_rev (rev), ver bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), updated_at timestamptz NOT NULL DEFAULT clock_timestamp(), CONSTRAINT edge_props_is_object CHECK (jsonb_typeof(props) = 'object'), CONSTRAINT edge_source_fk FOREIGN KEY (source_id, source_type) REFERENCES truss.object (id, type_id) ON DELETE RESTRICT, CONSTRAINT edge_target_fk FOREIGN KEY (target_id, target_type) REFERENCES truss.object (id, type_id) ON DELETE RESTRICT, CONSTRAINT edge_endpoint_types_fk FOREIGN KEY (rel_type_id, source_type, target_type) REFERENCES truss.rel_endpoint (rel_type_id, source_type, target_type)); CREATE UNIQUE INDEX edge_out ON truss.edge USING btree (source_id, rel_type_id, target_id) INCLUDE (target_type); CREATE INDEX edge_in ON truss.edge USING btree (target_id, rel_type_id) INCLUDE (source_id, source_type); CREATE TABLE truss.edge_limit (rel_type_id bigint NOT NULL, side char(1) NOT NULL CHECK (side IN ('s', 't')), endpoint_id bigint NOT NULL, edge_id bigint NOT NULL REFERENCES truss.edge (id) ON DELETE CASCADE, PRIMARY KEY (rel_type_id, side, endpoint_id)); CREATE INDEX edge_limit_edge ON truss.edge_limit USING btree (edge_id); CREATE TABLE truss.key_tombstone (entity_kind char(1) NOT NULL CHECK (entity_kind IN ('e')), type_id int NOT NULL, key_num smallint NOT NULL, k text NOT NULL COLLATE "C", entity_id bigint NOT NULL, ver bigint NOT NULL, at timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY (entity_kind, type_id, key_num, k), CONSTRAINT key_tombstone_edge_key CHECK (entity_kind = 'o' OR key_num = 0)); CREATE TABLE truss.record_source (entity_kind char(1) NOT NULL CHECK (entity_kind IN ('o', 'e')), entity_id bigint NOT NULL, load_id text NOT NULL, source jsonb NOT NULL DEFAULT ('{}'::jsonb), imported_at timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY (entity_kind, entity_id), CONSTRAINT record_source_is_object CHECK (jsonb_typeof(source) = 'object')); CREATE INDEX record_source_load ON truss.record_source USING btree (load_id); CREATE TABLE truss.feed_consumer (consumer text PRIMARY KEY, xid xid8 NOT NULL, seq bigint NOT NULL, updated_at timestamptz NOT NULL DEFAULT clock_timestamp()); CREATE SEQUENCE truss.journal_seq AS bigint INCREMENT 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 1 NO CYCLE CACHE 1; CREATE TABLE truss.journal (seq bigint NOT NULL DEFAULT nextval('truss.journal_seq'), at timestamptz NOT NULL DEFAULT clock_timestamp(), xid xid8 NOT NULL DEFAULT pg_current_xact_id(), entity_kind char(1) NOT NULL CHECK (entity_kind IN ('o', 'e')), entity_id bigint NOT NULL, entity_type int NOT NULL, ver bigint NOT NULL, op text NOT NULL CHECK (op IN ('create', 'update', 'delete', 'retain', 'rebind', 'transform', 'metadata')), prop_id int, old_value jsonb, new_value jsonb, rev int NOT NULL, origin jsonb NOT NULL DEFAULT ('{}'::jsonb), CONSTRAINT journal_pkey PRIMARY KEY (at, seq), CONSTRAINT journal_origin_is_object CHECK (jsonb_typeof(origin) = 'object')) PARTITION BY RANGE(at); CREATE INDEX journal_entity ON truss.journal USING btree (entity_kind, entity_id, ver); CREATE INDEX journal_feed ON truss.journal USING btree (xid, seq); CREATE INDEX journal_request ON truss.journal USING btree ((origin #>> '{request,id}')) WHERE origin ? 'request'; ALTER TABLE truss.edge ADD COLUMN retained pg_catalog.jsonb; ALTER TABLE truss.edge ADD CONSTRAINT edge_retained_is_object CHECK (retained IS NULL OR pg_catalog.jsonb_typeof(retained) = 'object'); ALTER TABLE truss.journal ADD CONSTRAINT journal_complete_payload CHECK (old_value IS NULL AND new_value IS NOT NULL AND (pg_catalog.jsonb_typeof(new_value) = 'object' AND (new_value ->> 'interfaceVersion') = 'truss-journal-exact-bytes/0.2.0-proposal' AND (new_value ->> 'component') = 'event') IS TRUE); ALTER TABLE truss.journal ADD CONSTRAINT journal_complete_origin CHECK ((pg_catalog.jsonb_typeof(origin) = 'object' AND (origin ->> 'interfaceVersion') = 'truss-journal-exact-bytes/0.2.0-proposal' AND (origin ->> 'component') = 'origin') IS TRUE); ALTER TABLE truss.journal ADD CONSTRAINT journal_complete_property_mapping CHECK (((op IN ('update', 'transform', 'rebind') AND prop_id IS NOT NULL) OR (op IN ('create', 'delete', 'retain', 'metadata') AND prop_id IS NULL)) IS TRUE); ALTER TABLE truss.journal ADD CONSTRAINT journal_complete_positive_identity CHECK (entity_id > 0 AND ver > 0 AND seq > 0); CREATE TABLE truss.row_home_operation (original_writer_xid xid8 NOT NULL, operation_ordinal bigint NOT NULL, operation_kind text NOT NULL COLLATE pg_catalog."C", phase text NOT NULL COLLATE pg_catalog."C", effect_generation bigint NOT NULL, readiness_generation bigint, sealed_generation bigint, application_generation bigint, original_context_bytes bytea NOT NULL, original_definition_bytes bytea NOT NULL, original_input_bytes bytea NOT NULL, original_prestate_bytes bytea NOT NULL, admitted_candidate_bytes bytea NOT NULL, effect_obligation_bytes bytea NOT NULL, original_group_custody_bytes bytea NOT NULL, application_result_bytes bytea, CONSTRAINT row_home_operation_pk PRIMARY KEY (original_writer_xid, operation_ordinal), CONSTRAINT row_home_operation_identity CHECK (operation_ordinal >= 0), CONSTRAINT row_home_operation_kind CHECK (operation_kind IN ('mutation', 'import', 'catalog-transform', 'catalog-acceptance', 'home-migration', 'administrative-repair')), CONSTRAINT row_home_operation_generation CHECK (effect_generation >= 0 AND (readiness_generation IS NULL OR readiness_generation = effect_generation) AND (sealed_generation IS NULL OR sealed_generation = effect_generation) AND (application_generation IS NULL OR application_generation = effect_generation)), CONSTRAINT row_home_operation_phase CHECK ((phase = 'admitted' AND readiness_generation IS NULL AND sealed_generation IS NULL AND application_generation IS NULL AND application_result_bytes IS NULL) OR (phase = 'effects_ready' AND readiness_generation IS NOT NULL AND sealed_generation IS NULL AND application_generation IS NULL AND application_result_bytes IS NULL) OR (phase = 'row_sealed' AND readiness_generation IS NOT NULL AND sealed_generation IS NOT NULL AND application_generation IS NULL AND application_result_bytes IS NULL) OR (phase = 'application_finalized' AND readiness_generation IS NOT NULL AND sealed_generation IS NOT NULL AND application_generation IS NOT NULL AND application_result_bytes IS NOT NULL AND octet_length(application_result_bytes) > 0)), CONSTRAINT row_home_operation_originals CHECK (octet_length(original_context_bytes) > 0 AND octet_length(original_definition_bytes) > 0 AND octet_length(original_input_bytes) > 0 AND octet_length(original_prestate_bytes) > 0 AND octet_length(admitted_candidate_bytes) > 0 AND octet_length(effect_obligation_bytes) > 0 AND octet_length(original_group_custody_bytes) > 0)); CREATE TABLE truss.row_home_journal_stage (original_writer_xid pg_catalog.xid8 NOT NULL, operation_ordinal bigint NOT NULL, stage_name pg_catalog.text NOT NULL COLLATE pg_catalog."C", stage_ordinal bigint NOT NULL, effect_generation bigint NOT NULL, body_bytes pg_catalog.bytea NOT NULL, CONSTRAINT row_home_journal_stage_pk PRIMARY KEY (original_writer_xid, operation_ordinal, stage_name, stage_ordinal), CONSTRAINT row_home_journal_stage_operation_fk FOREIGN KEY (original_writer_xid, operation_ordinal) REFERENCES truss.row_home_operation (original_writer_xid, operation_ordinal) ON DELETE RESTRICT, CONSTRAINT row_home_journal_stage_phase CHECK (stage_name IN ('start', 'transition', 'final', 'reserved', 'publication')), CONSTRAINT row_home_journal_stage_ordinals CHECK (operation_ordinal >= 0 AND stage_ordinal >= 0 AND effect_generation >= 0 AND (stage_name = 'transition' OR stage_ordinal = 0)), CONSTRAINT row_home_journal_stage_body CHECK (pg_catalog.octet_length(body_bytes) > 0)); CREATE INDEX type_def_lineage_route ON truss.type_def USING btree (lineage_sha256, type_id); ALTER TABLE truss.prop_def ADD CONSTRAINT prop_def_owner_property_row_home UNIQUE (type_id, prop_id); ALTER TABLE truss.edge ADD CONSTRAINT edge_typed_identity_row_home UNIQUE (id, rel_type_id); CREATE SEQUENCE truss.row_home_id_seq AS bigint NO CYCLE; CREATE TABLE truss.row_home_state (state_id bigint PRIMARY KEY DEFAULT nextval('truss.row_home_id_seq'), owner_kind text NOT NULL COLLATE pg_catalog."C", object_id bigint, object_type_id int, edge_id bigint, relationship_type_id int, property_owner_type_id int NOT NULL, property_id int NOT NULL, root_node_id bigint NOT NULL, definition_bytes bytea NOT NULL, home_profile_bytes bytea NOT NULL, value_profile_bytes bytea NOT NULL, source_bytes bytea NOT NULL, CONSTRAINT row_home_state_positive_ids CHECK (state_id > 0 AND root_node_id > 0), CONSTRAINT row_home_state_kind CHECK ((owner_kind = 'object' AND object_id IS NOT NULL AND object_type_id IS NOT NULL AND edge_id IS NULL AND relationship_type_id IS NULL AND property_owner_type_id = object_type_id) OR (owner_kind = 'edge' AND edge_id IS NOT NULL AND relationship_type_id IS NOT NULL AND object_id IS NULL AND object_type_id IS NULL)), CONSTRAINT row_home_state_property_fk FOREIGN KEY (property_owner_type_id, property_id) REFERENCES truss.prop_def (type_id, prop_id), CONSTRAINT row_home_state_object_fk FOREIGN KEY (object_id, object_type_id) REFERENCES truss.object (id, type_id) ON DELETE CASCADE, CONSTRAINT row_home_state_edge_fk FOREIGN KEY (edge_id, relationship_type_id) REFERENCES truss.edge (id, rel_type_id) ON DELETE CASCADE, CONSTRAINT row_home_state_object_property UNIQUE (object_id, object_type_id, property_id), CONSTRAINT row_home_state_edge_property UNIQUE (edge_id, relationship_type_id, property_id), CONSTRAINT row_home_state_carriers_nonempty CHECK (octet_length(definition_bytes) > 0 AND octet_length(home_profile_bytes) > 0 AND octet_length(value_profile_bytes) > 0 AND octet_length(source_bytes) > 0)); CREATE TABLE truss.row_home_node (state_id bigint NOT NULL REFERENCES truss.row_home_state (state_id) ON DELETE CASCADE, node_id bigint NOT NULL DEFAULT nextval('truss.row_home_id_seq'), parent_node_id bigint, slot_kind text NOT NULL COLLATE pg_catalog."C", sequence_ordinal bigint, map_key text COLLATE pg_catalog."C", record_field_identity_bytes bytea, value_kind text NOT NULL COLLATE pg_catalog."C", definition_bytes bytea NOT NULL, source_bytes bytea NOT NULL, CONSTRAINT row_home_node_pk P