EATE TABLE truss.row_home_scalar (state_id bigint NOT NULL, node_id bigint NOT NULL, scalar_kind text NOT NULL COLLATE pg_catalog."C", text_value text COLLATE pg_catalog."C", boolean_value boolean, numeric_value numeric, numeric_token text COLLATE pg_catalog."C", binary_value bytea, temporal_text text COLLATE pg_catalog."C", temporal_instant timestamptz, opaque_bytes bytea, codec_definition_bytes bytea NOT NULL, original_source_bytes bytea NOT NULL, CONSTRAINT row_home_scalar_pk PRIMARY KEY (state_id, node_id), CONSTRAINT row_home_scalar_node_fk FOREIGN KEY (state_id, node_id) REFERENCES truss.row_home_node (state_id, node_id) ON DELETE CASCADE, CONSTRAINT row_home_scalar_carriers_nonempty CHECK (octet_length(codec_definition_bytes) > 0 AND octet_length(original_source_bytes) > 0), CONSTRAINT row_home_scalar_family CHECK ((scalar_kind = 'string' AND text_value IS NOT NULL AND boolean_value IS NULL AND numeric_value IS NULL AND numeric_token IS NULL AND binary_value IS NULL AND temporal_text IS NULL AND temporal_instant IS NULL AND opaque_bytes IS NULL) OR (scalar_kind = 'boolean' AND boolean_value IS NOT NULL AND text_value IS NULL AND numeric_value IS NULL AND numeric_token IS NULL AND binary_value IS NULL AND temporal_text IS NULL AND temporal_instant IS NULL AND opaque_bytes IS NULL) OR (scalar_kind IN ('integer', 'decimal') AND numeric_value IS NOT NULL AND numeric_token IS NOT NULL AND octet_length(numeric_token) > 0 AND numeric_value::text COLLATE pg_catalog."C" NOT IN ('NaN', 'Infinity', '-Infinity') AND (scalar_kind = 'decimal' OR numeric_value = pg_catalog.trunc(numeric_value)) AND text_value IS NULL AND boolean_value IS NULL AND binary_value IS NULL AND temporal_text IS NULL AND temporal_instant IS NULL AND opaque_bytes IS NULL) OR (scalar_kind = 'binary' AND binary_value IS NOT NULL AND text_value IS NULL AND boolean_value IS NULL AND numeric_value IS NULL AND numeric_token IS NULL AND temporal_text IS NULL AND temporal_instant IS NULL AND opaque_bytes IS NULL) OR (scalar_kind = 'timestamp' AND temporal_text IS NOT NULL AND text_value IS NULL AND boolean_value IS NULL AND numeric_value IS NULL AND numeric_token IS NULL AND binary_value IS NULL AND opaque_bytes IS NULL) OR (scalar_kind = 'opaque' AND opaque_bytes IS NOT NULL AND text_value IS NULL AND boolean_value IS NULL AND numeric_value IS NULL AND numeric_token IS NULL AND binary_value IS NULL AND temporal_text IS NULL AND temporal_instant IS NULL))); CREATE TABLE truss.relationship_lineage (rel_type_id int PRIMARY KEY REFERENCES truss.rel_def (rel_type_id) ON DELETE RESTRICT, lineage_category text NOT NULL, identity_profile text NOT NULL, original_identity_bytes bytea NOT NULL, identity_sha256 bytea GENERATED ALWAYS AS (pg_catalog.sha256(original_identity_bytes)) STORED, CONSTRAINT relationship_lineage_category CHECK (lineage_category IN ('authored', 'composition_field')), CONSTRAINT relationship_lineage_profile_nonempty CHECK (length(identity_profile) > 0), CONSTRAINT relationship_lineage_identity_nonempty CHECK (octet_length(original_identity_bytes) > 0)); CREATE INDEX relationship_lineage_route ON truss.relationship_lineage USING btree (identity_sha256, rel_type_id); ALTER TABLE truss.schema_doc ALTER COLUMN doc_id TYPE text COLLATE pg_catalog."C"; ALTER TABLE truss.schema_doc ADD CONSTRAINT schema_doc_definition_source_tuple UNIQUE (rev, ord, doc_id); ALTER TABLE truss.type_def ADD COLUMN definition_source_kind text COLLATE pg_catalog."C", ADD COLUMN definition_rev int, ADD COLUMN definition_doc_ord int, ADD COLUMN definition_document_id text COLLATE pg_catalog."C", ADD COLUMN binding_source_rev int, ADD COLUMN binding_source_pointer text COLLATE pg_catalog."C", ADD COLUMN binding_source_bytes bytea, ADD CONSTRAINT type_def_definition_document_fk FOREIGN KEY (definition_rev, definition_doc_ord, definition_document_id) REFERENCES truss.schema_doc (rev, ord, doc_id), ADD CONSTRAINT type_def_definition_binding_revision_fk FOREIGN KEY (binding_source_rev) REFER